<dialog id="face-enrollment" class="m-auto w-full max-w-xl rounded-2xl p-6 backdrop:bg-slate-950/60"><form method="post" enctype="multipart/form-data" action="{{ route('personnel.face.store',$personnel) }}">@csrf<h2 class="text-lg font-bold text-emerald-950">Pendaftaran Wajah</h2><ul class="my-3 list-disc pl-5 text-sm text-slate-600"><li>Hadapkan wajah ke kamera.</li><li>Pastikan pencahayaan cukup.</li><li>Lepaskan masker/kacamata gelap jika mengganggu.</li><li>Pastikan hanya satu orang terlihat.</li></ul><video id="face-video" class="aspect-video w-full rounded-xl bg-slate-900" autoplay muted playsinline></video><canvas id="face-canvas" class="hidden"></canvas><p id="face-camera-error" class="my-3 hidden rounded-xl bg-red-50 p-3 text-sm text-red-700" role="alert"></p><p id="face-step" class="my-3 font-semibold">Capture 1: wajah menghadap depan</p>@foreach(['front','left','right'] as $pose)<input type="file" name="{{ $pose }}" hidden required>@endforeach<div class="flex gap-2"><button id="face-capture" type="button" class="btn btn-primary" disabled>Ambil Foto</button><button type="button" class="btn btn-secondary" data-face-close>Batal</button><button id="face-submit" class="btn btn-primary hidden">Validasi & Simpan</button></div></form></dialog>
@push('scripts')<script>(()=>{const d=document.getElementById('face-enrollment'),open=document.getElementById('face-enrollment-open'),v=document.getElementById('face-video'),c=document.getElementById('face-canvas'),b=document.getElementById('face-capture'),submit=document.getElementById('face-submit'),label=document.getElementById('face-step'),error=document.getElementById('face-camera-error'),poses=['front','left','right'],directions=['depan','sedikit ke kiri','sedikit ke kanan'];let i=0;const stop=()=>{v?.srcObject?.getTracks().forEach(track=>track.stop());if(v)v.srcObject=null};const fail=message=>{error.textContent=message;error.classList.remove('hidden');b.disabled=true};open?.addEventListener('click',async()=>{i=0;d.querySelectorAll('input[type="file"]').forEach(input=>input.value='');label.textContent='Capture 1: wajah menghadap depan';b.classList.remove('hidden');submit.classList.add('hidden');b.disabled=true;d.showModal();error.classList.add('hidden');if(!window.isSecureContext&&!['localhost','127.0.0.1'].includes(location.hostname)){fail('Kamera hanya dapat digunakan melalui koneksi HTTPS.');return}if(!navigator.mediaDevices?.getUserMedia){fail('Peramban ini tidak mendukung akses kamera.');return}try{const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user'},audio:false});v.srcObject=stream;await v.play();b.disabled=false}catch(e){fail(e.name==='NotAllowedError'?'Izin kamera ditolak. Izinkan akses kamera pada pengaturan peramban lalu coba lagi.':'Kamera tidak dapat dibuka. Pastikan kamera tersedia dan tidak sedang digunakan aplikasi lain.')}});d?.querySelector('[data-face-close]')?.addEventListener('click',()=>d.close());d?.addEventListener('close',stop);b?.addEventListener('click',()=>{if(!v.videoWidth||!v.videoHeight){fail('Kamera belum siap. Tunggu beberapa saat lalu coba lagi.');return}c.width=v.videoWidth;c.height=v.videoHeight;c.getContext('2d').drawImage(v,0,0);c.toBlob(blob=>{if(!blob){fail('Foto gagal diambil. Silakan coba lagi.');return}const input=d.querySelector(`[name="${poses[i]}"]`),file=new File([blob],`${poses[i]}.jpg`,{type:'image/jpeg'}),dt=new DataTransfer;dt.items.add(file);input.files=dt.files;i++;if(i===3){b.classList.add('hidden');submit.classList.remove('hidden');label.textContent='Tiga foto siap divalidasi oleh layanan wajah.';stop()}else label.textContent=`Capture ${i+1}: wajah ${directions[i]}`},'image/jpeg',.92)});})();</script>@endpush
